@import url('https://fonts.googleapis.com/css2?family=EB+Garamond:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Aesop DNA — apothecary editorial: paper cream, humanist serif, quiet sage calm */
.theme-aesop-dna {
  --bg: oklch(0.995 0.016 102.8);
  --surface: oklch(0.971 0.016 102.8);
  --surface-2: oklch(0.941 0.016 102.8);
  --fg: oklch(0.320 0.005 106.7);
  --fg-muted: oklch(0.563 0.011 113.3);
  --accent: oklch(0.320 0.005 106.7);
  --accent-fg: oklch(0.995 0.016 102.8);
  --accent-2: oklch(0.721 0.021 135.9);
  --line: oklch(0.852 0.014 106.7);
  --success: oklch(0.529 0.033 148.2);
  --warning: oklch(0.661 0.105 84.9);
  --danger: oklch(0.510 0.113 31.3);
  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;
  --shadow-1: none;
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px oklch(0.35 0.005 100);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "EB Garamond", Georgia, serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: none;
  --label-tracking: 0.14em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-aesop-dna h1,
.theme-aesop-dna h2,
.theme-aesop-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-aesop-dna h1 { font-weight: 400; }
.theme-aesop-dna button { text-transform: uppercase; letter-spacing: 0.18em; font-size: 12px; }
.theme-aesop-dna ::selection { background: oklch(0.75 0.03 130); }

/* depth */
.theme-aesop-dna thead th { font-family: var(--font-display); font-style: italic; font-weight: 500; font-size: 0.95rem; letter-spacing: 0.02em; border-bottom: 1px solid var(--fg); }
.theme-aesop-dna td { border-bottom: 1px solid var(--line); }
.theme-aesop-dna tbody tr:hover { background: var(--surface); }
.theme-aesop-dna input, .theme-aesop-dna select, .theme-aesop-dna textarea { background: transparent; border: none; border-bottom: 1px solid var(--fg-muted); border-radius: 0; }
.theme-aesop-dna textarea { border: 1px solid var(--line); }
.theme-aesop-dna input:focus-visible, .theme-aesop-dna select:focus-visible, .theme-aesop-dna textarea:focus-visible { outline: none; border-color: var(--fg); }
.theme-aesop-dna a { color: var(--fg); text-decoration: underline; text-decoration-color: var(--accent-2); text-decoration-thickness: 1px; text-underline-offset: 4px; }
.theme-aesop-dna a:hover { text-decoration-color: var(--fg); }
.theme-aesop-dna ::-webkit-scrollbar { width: 8px; }
.theme-aesop-dna ::-webkit-scrollbar-track { background: var(--bg); }
.theme-aesop-dna ::-webkit-scrollbar-thumb { background: var(--line); border-radius: 0; }
.theme-aesop-dna kbd { font-family: var(--font-mono); font-size: 0.68em; letter-spacing: 0.08em; background: var(--surface); border: 1px solid var(--line); border-radius: 0; padding: 0.15em 0.5em; }
.theme-aesop-dna .label-caps { text-transform: uppercase; font-size: 0.68rem; color: var(--fg-muted); }
.theme-aesop-dna .themed-border { border-color: var(--fg); }
.theme-aesop-dna button { transition: background 220ms ease, color 220ms ease; }
.theme-aesop-dna button:hover { background: var(--fg); color: var(--bg); }

/* alt mode: amber-glass apothecary — the brown bottle, cream label */
.theme-aesop-dna.alt-mode {
  --bg: oklch(0.200 0.014 85.0);
  --surface: oklch(0.240 0.016 85.0);
  --surface-2: oklch(0.280 0.018 85.0);
  --fg: oklch(0.92 0.020 95);
  --fg-muted: oklch(0.68 0.020 95);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --accent: oklch(0.88 0.030 95);
  --accent-fg: oklch(0.220 0.014 85);
  --accent-2: oklch(0.62 0.030 135.9);
}
.theme-aesop-dna.alt-mode ::selection { background: oklch(0.42 0.05 130); }
.theme-aesop-dna.alt-mode button:hover { background: var(--fg); color: var(--bg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
